cat > src/command.rs <<'EOF'
//! Turns one input line into a typed command, applying the spec's check order.

use std::ops::RangeInclusive;

use serde_json::{Map, Value};

use crate::error::{Error, ErrorCode, Result};
use crate::queue::QueueName;

pub type Object = Map<String, Value>;

/// Parses a line as UTF-8 JSON and requires it to be an object.
pub fn parse_line(line: &[u8]) -> Result<Object> {
    let bad = |what: &str| Error::new(ErrorCode::InvalidRequest, what.to_owned());
    let text = std::str::from_utf8(line).map_err(|_| bad("line is not valid UTF-8"))?;
    match serde_json::from_str(text) {
        Ok(Value::Object(object)) => Ok(object),
        _ => Err(bad("line is not a JSON object")),
    }
}

/// Attributes as given in a request; ranges and types are already checked.
#[derive(Debug, Default)]
pub struct AttributeInput<'a> {
    pub visibility_timeout: Option<u32>,
    pub delay_seconds: Option<u32>,
    pub retention_seconds: Option<u32>,
    pub fifo: Option<bool>,
    pub content_based_deduplication: Option<bool>,
    pub dead_letter_queue: Option<&'a str>,
    pub max_receive_count: Option<u32>,
}

impl<'a> AttributeInput<'a> {
    /// The dead-letter configuration, which must be given whole or not at all.
    pub fn dead_letter(&self) -> Result<Option<(&'a str, u32)>> {
        match (self.dead_letter_queue, self.max_receive_count) {
            (Some(queue), Some(count)) => Ok(Some((queue, count))),
            (None, None) => Ok(None),
            _ => Err(Error::invalid(
                "DeadLetterQueue and MaxReceiveCount",
                "must be given together",
            )),
        }
    }
}

const ATTRIBUTE_NAMES: [&str; 7] = [
    "VisibilityTimeout",
    "DelaySeconds",
    "RetentionSeconds",
    "Fifo",
    "ContentBasedDeduplication",
    "DeadLetterQueue",
    "MaxReceiveCount",
];

#[derive(Debug)]
pub enum Command<'a> {
    CreateQueue { name: QueueName, attributes: AttributeInput<'a> },
    SetQueueAttributes { queue: &'a str, attributes: AttributeInput<'a> },
    GetQueueAttributes { queue: &'a str },
    ListQueues { prefix: Option<&'a str> },
    DeleteQueue { queue: &'a str },
    PurgeQueue { queue: &'a str },
    Tick { seconds: u32 },
    SendMessage {
        queue: &'a str,
        body: &'a str,
        delay_seconds: Option<u32>,
        group_id: Option<&'a str>,
        deduplication_id: Option<&'a str>,
    },
    ReceiveMessage { queue: &'a str, max_messages: usize, visibility_timeout: Option<u32> },
    DeleteMessage { queue: &'a str, receipt_handle: &'a str },
    ChangeMessageVisibility { queue: &'a str, receipt_handle: &'a str, visibility_timeout: u32 },
}

/// Read access to the members of an object, where `null` counts as absent.
struct Params<'a>(&'a Object);

impl<'a> Params<'a> {
    fn get(&self, name: &str) -> Option<&'a Value> {
        self.0.get(name).filter(|value| !value.is_null())
    }

    fn require(&self, names: &[&str]) -> Result<()> {
        match names.iter().find(|name| self.get(name).is_none()) {
            Some(name) => Err(Error::missing(name)),
            None => Ok(()),
        }
    }

    fn string(&self, name: &str) -> Result<Option<&'a str>> {
        self.get(name)
            .map(|value| value.as_str().ok_or_else(|| Error::invalid(name, "must be a string")))
            .transpose()
    }

    fn integer(&self, name: &str, range: RangeInclusive<u32>) -> Result<Option<u32>> {
        self.get(name)
            .map(|value| {
                value
                    .as_i64()
                    .and_then(|n| u32::try_from(n).ok())
                    .filter(|n| range.contains(n))
                    .ok_or_else(|| {
                        let message = format!("must be an integer from {} to {}", range.start(), range.end());
                        Error::invalid(name, &message)
                    })
            })
            .transpose()
    }

    fn boolean(&self, name: &str) -> Result<Option<bool>> {
        self.get(name)
            .map(|value| value.as_bool().ok_or_else(|| Error::invalid(name, "must be a boolean")))
            .transpose()
    }

    /// A string of 1 to 128 characters from `A-Z a-z 0-9 _ -`.
    fn identifier(&self, name: &str) -> Result<Option<&'a str>> {
        let value = self.string(name)?;
        match value {
            Some(text) if !(1..=128).contains(&text.len()) || !text.bytes().all(is_name_byte) => {
                Err(Error::invalid(name, "must be 1 to 128 characters of A-Z a-z 0-9 _ -"))
            }
            _ => Ok(value),
        }
    }

    fn attributes(&self, name: &str) -> Result<AttributeInput<'a>> {
        let object = match self.get(name) {
            None => return Ok(AttributeInput::default()),
            Some(Value::Object(object)) => object,
            Some(_) => return Err(Error::invalid(name, "must be an object")),
        };
        if let Some(unknown) = object.keys().find(|key| !ATTRIBUTE_NAMES.contains(&key.as_str())) {
            return Err(Error::invalid("Attributes", &format!("has unknown attribute {unknown}")));
        }
        let attrs = Params(object);
        Ok(AttributeInput {
            visibility_timeout: attrs.integer("VisibilityTimeout", 0..=43200)?,
            delay_seconds: attrs.integer("DelaySeconds", 0..=900)?,
            retention_seconds: attrs.integer("RetentionSeconds", 60..=1_209_600)?,
            fifo: attrs.boolean("Fifo")?,
            content_based_deduplication: attrs.boolean("ContentBasedDeduplication")?,
            dead_letter_queue: attrs.string("DeadLetterQueue")?,
            max_receive_count: attrs.integer("MaxReceiveCount", 1..=1000)?,
        })
    }
}

pub fn is_name_byte(byte: u8) -> bool {
    byte.is_ascii_alphanumeric() || byte == b'_' || byte == b'-'
}

impl<'a> Command<'a> {
    pub fn parse(object: &'a Object) -> Result<Self> {
        let params = Params(object);
        let name = match object.get("Command") {
            Some(Value::String(name)) => name.as_str(),
            _ => return Err(Error::new(ErrorCode::InvalidRequest, "Command must be a string")),
        };
        // Every command with a queue requires `QueueName` first.
        let queue = |params: &Params<'a>, more: &[&str]| -> Result<&'a str> {
            let mut required = vec!["QueueName"];
            required.extend_from_slice(more);
            params.require(&required)?;
            Ok(params.string("QueueName")?.unwrap_or_default())
        };
        match name {
            "CreateQueue" => {
                params.require(&["QueueName"])?;
                let raw = params.string("QueueName")?.unwrap_or_default();
                let name = QueueName::new(raw)?;
                let attributes = params.attributes("Attributes")?;
                Ok(Self::CreateQueue { name, attributes })
            }
            "SetQueueAttributes" => {
                let queue = queue(&params, &["Attributes"])?;
                let attributes = params.attributes("Attributes")?;
                Ok(Self::SetQueueAttributes { queue, attributes })
            }
            "GetQueueAttributes" => Ok(Self::GetQueueAttributes { queue: queue(&params, &[])? }),
            "DeleteQueue" => Ok(Self::DeleteQueue { queue: queue(&params, &[])? }),
            "PurgeQueue" => Ok(Self::PurgeQueue { queue: queue(&params, &[])? }),
            "ListQueues" => Ok(Self::ListQueues { prefix: params.string("Prefix")? }),
            "Tick" => {
                params.require(&["Seconds"])?;
                let seconds = params.integer("Seconds", 0..=1_209_600)?.unwrap_or_default();
                Ok(Self::Tick { seconds })
            }
            "SendMessage" => {
                let queue = queue(&params, &["Body"])?;
                let body = params.string("Body")?.unwrap_or_default();
                if !(1..=1024).contains(&body.len()) {
                    return Err(Error::invalid("Body", "must be 1 to 1024 bytes"));
                }
                Ok(Self::SendMessage {
                    queue,
                    body,
                    delay_seconds: params.integer("DelaySeconds", 0..=900)?,
                    group_id: params.identifier("GroupId")?,
                    deduplication_id: params.identifier("DeduplicationId")?,
                })
            }
            "ReceiveMessage" => {
                let queue = queue(&params, &[])?;
                let max_messages = params.integer("MaxMessages", 1..=10)?.unwrap_or(1);
                Ok(Self::ReceiveMessage {
                    queue,
                    max_messages: usize::try_from(max_messages).unwrap_or(1),
                    visibility_timeout: params.integer("VisibilityTimeout", 0..=43200)?,
                })
            }
            "DeleteMessage" => {
                let queue = queue(&params, &["ReceiptHandle"])?;
                let receipt_handle = params.string("ReceiptHandle")?.unwrap_or_default();
                Ok(Self::DeleteMessage { queue, receipt_handle })
            }
            "ChangeMessageVisibility" => {
                let queue = queue(&params, &["ReceiptHandle", "VisibilityTimeout"])?;
                let receipt_handle = params.string("ReceiptHandle")?.unwrap_or_default();
                let visibility_timeout =
                    params.integer("VisibilityTimeout", 0..=43200)?.unwrap_or_default();
                Ok(Self::ChangeMessageVisibility { queue, receipt_handle, visibility_timeout })
            }
            _ => Err(Error::new(ErrorCode::InvalidRequest, format!("unknown command {name}"))),
        }
    }
}
