use std::borrow::Borrow;
use std::collections::{BTreeMap, HashMap, HashSet};
use std::fmt;

use crate::command::is_name_byte;
use crate::error::{Error, ErrorCode, Result};

pub const MAX_MESSAGES: usize = 100_000;
const DEDUP_WINDOW: u64 = 300;

/// A queue name that follows the name syntax.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord)]
pub struct QueueName(String);

impl QueueName {
    pub fn new(raw: &str) -> Result<Self> {
        let (stem, max) = match raw.strip_suffix(".fifo") {
            Some(stem) => (stem, 75),
            None => (raw, 80),
        };
        if (1..=max).contains(&stem.len()) && stem.bytes().all(is_name_byte) {
            Ok(Self(raw.to_owned()))
        } else {
            Err(Error::new(ErrorCode::QueueNameInvalid, format!("invalid queue name {raw:?}")))
        }
    }

    pub fn as_str(&self) -> &str {
        &self.0
    }
}

impl Borrow<str> for QueueName {
    fn borrow(&self) -> &str {
        &self.0
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct MessageId(pub u64);

impl fmt::Display for MessageId {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "m-{}", self.0)
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct ReceiptHandle(pub u64);

impl fmt::Display for ReceiptHandle {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "r-{}", self.0)
    }
}

impl ReceiptHandle {
    /// Parses the canonical text of a handle below `next`, the first number not yet issued.
    pub fn parse_issued(text: &str, next: u64) -> Option<Self> {
        let digits = text.strip_prefix("r-")?;
        if digits.starts_with('0') || !digits.bytes().all(|b| b.is_ascii_digit()) {
            return None;
        }
        digits.parse().ok().filter(|n| *n < next).map(Self)
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct DeadLetter {
    pub queue: QueueName,
    pub max_receive_count: u32,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Attributes {
    pub visibility_timeout: u32,
    pub delay_seconds: u32,
    pub retention_seconds: u32,
    pub fifo: bool,
    pub content_based_deduplication: bool,
    pub dead_letter: Option<DeadLetter>,
}

impl Default for Attributes {
    fn default() -> Self {
        Self {
            visibility_timeout: 30,
            delay_seconds: 0,
            retention_seconds: 345_600,
            fifo: false,
            content_based_deduplication: false,
            dead_letter: None,
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Hold {
    Released,
    Delayed { until: u64 },
    InFlight { until: u64, handle: ReceiptHandle },
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum State {
    Visible,
    InFlight,
    Delayed,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Fifo {
    pub group: String,
    pub sequence: u64,
}

#[derive(Debug, Clone)]
pub struct Message {
    pub id: MessageId,
    pub body: String,
    pub sent_at: u64,
    pub receive_count: u32,
    pub first_received_at: Option<u64>,
    pub fifo: Option<Fifo>,
    pub hold: Hold,
}

impl Message {
    pub fn state(&self, now: u64) -> State {
        match self.hold {
            Hold::Delayed { until } if now < until => State::Delayed,
            Hold::InFlight { until, .. } if now < until => State::InFlight,
            _ => State::Visible,
        }
    }
}

/// Where a deduplication id was last accepted.
#[derive(Debug, Clone, Copy)]
pub struct Original {
    pub accepted_at: u64,
    pub id: MessageId,
    pub sequence: u64,
}

pub struct Delivery {
    pub delivered: Vec<Message>,
    pub dead: Option<(QueueName, Vec<Message>)>,
}

#[derive(Debug)]
pub struct Queue {
    pub attributes: Attributes,
    messages: BTreeMap<u64, Message>,
    next_arrival: u64,
    next_sequence: u64,
    /// Latest handle to arrival key; entries are checked against the message on use.
    handles: HashMap<ReceiptHandle, u64>,
    dedup: HashMap<String, Original>,
    /// The clock value at which retention was last applied; `None` forces a sweep.
    swept_at: Option<u64>,
}

impl Queue {
    pub fn new(attributes: Attributes) -> Self {
        Self {
            attributes,
            messages: BTreeMap::new(),
            next_arrival: 0,
            next_sequence: 1,
            handles: HashMap::new(),
            dedup: HashMap::new(),
            swept_at: None,
        }
    }

    pub fn len(&self) -> usize {
        self.messages.len()
    }

    pub fn is_full(&self) -> bool {
        self.messages.len() >= MAX_MESSAGES
    }

    /// Applies retention. Messages sent at `now` never expire at `now`, so one sweep per
    /// clock value is enough.
    pub fn sweep(&mut self, now: u64) {
        if self.swept_at == Some(now) {
            return;
        }
        let retention = u64::from(self.attributes.retention_seconds);
        let expired: Vec<u64> = self
            .messages
            .iter()
            .filter(|(_, m)| now >= m.sent_at + retention)
            .map(|(key, _)| *key)
            .collect();
        for key in expired {
            self.remove(key);
        }
        self.swept_at = Some(now);
    }

    pub fn set_retention(&mut self, seconds: u32, now: u64) {
        self.attributes.retention_seconds = seconds;
        self.swept_at = None;
        self.sweep(now);
    }

    fn remove(&mut self, key: u64) -> Option<Message> {
        let message = self.messages.remove(&key)?;
        if let Hold::InFlight { handle, .. } = message.hold {
            self.handles.remove(&handle);
        }
        Some(message)
    }

    pub fn purge(&mut self) {
        self.messages.clear();
        self.handles.clear();
    }

    pub fn counts(&self, now: u64) -> [usize; 3] {
        let mut counts = [0; 3];
        for message in self.messages.values() {
            counts[match message.state(now) {
                State::Visible => 0,
                State::InFlight => 1,
                State::Delayed => 2,
            }] += 1;
        }
        counts
    }

    /// Appends a message; a FIFO queue gives it the next sequence number.
    pub fn add(&mut self, id: MessageId, body: String, sent_at: u64, group: Option<String>, hold: Hold) -> Option<u64> {
        let fifo = group.map(|group| {
            let sequence = self.next_sequence;
            self.next_sequence += 1;
            Fifo { group, sequence }
        });
        let sequence = fifo.as_ref().map(|f| f.sequence);
        let message = Message { id, body, sent_at, receive_count: 0, first_received_at: None, fifo, hold };
        self.messages.insert(self.next_arrival, message);
        self.next_arrival += 1;
        sequence
    }

    /// Accepts a message moved here from another queue, unless it is already too old.
    pub fn add_dead(&mut self, message: Message, now: u64) {
        if now < message.sent_at + u64::from(self.attributes.retention_seconds) {
            let group = message.fifo.map(|f| f.group);
            self.add(message.id, message.body, message.sent_at, group, Hold::Released);
        }
    }

    pub fn duplicate_of(&self, dedup_id: &str, now: u64) -> Option<Original> {
        self.dedup.get(dedup_id).copied().filter(|o| now - o.accepted_at < DEDUP_WINDOW)
    }

    pub fn record_dedup(&mut self, dedup_id: &str, original: Original) {
        self.dedup.insert(dedup_id.to_owned(), original);
    }

    pub fn receive(&mut self, now: u64, max: usize, visibility: u32, next_receipt: &mut u64) -> Delivery {
        let limit = self.attributes.dead_letter.as_ref().map(|d| d.max_receive_count);
        let mut seen_groups: HashSet<String> = HashSet::new();
        let mut delivered = Vec::new();
        let mut dead_keys = Vec::new();
        for (key, message) in &mut self.messages {
            if delivered.len() == max {
                break;
            }
            let first_in_group = message.fifo.as_ref().is_none_or(|f| !seen_groups.contains(&f.group));
            let eligible = first_in_group && message.state(now) == State::Visible;
            if eligible && limit.is_some_and(|l| message.receive_count >= l) {
                dead_keys.push(*key);
                continue;
            }
            if let Some(fifo) = message.fifo.as_ref().filter(|_| first_in_group) {
                seen_groups.insert(fifo.group.clone());
            }
            if !eligible {
                continue;
            }
            if let Hold::InFlight { handle, .. } = message.hold {
                self.handles.remove(&handle);
            }
            let handle = ReceiptHandle(*next_receipt);
            *next_receipt += 1;
            message.receive_count += 1;
            message.first_received_at.get_or_insert(now);
            message.hold = Hold::InFlight { until: now + u64::from(visibility), handle };
            self.handles.insert(handle, *key);
            delivered.push(message.clone());
        }
        let moved: Vec<Message> = dead_keys.into_iter().filter_map(|key| self.remove(key)).collect();
        let dead = self
            .attributes
            .dead_letter
            .as_ref()
            .filter(|_| !moved.is_empty())
            .map(|d| (d.queue.clone(), moved));
        Delivery { delivered, dead }
    }

    /// The arrival key of the message whose latest handle is `handle` and which is in flight.
    pub fn in_flight_key(&self, handle: ReceiptHandle, now: u64) -> Result<u64> {
        let live = self.handles.get(&handle).copied().filter(|key| {
            self.messages.get(key).is_some_and(|m| {
                m.state(now) == State::InFlight && matches!(m.hold, Hold::InFlight { handle: h, .. } if h == handle)
            })
        });
        live.ok_or_else(|| Error::new(ErrorCode::ReceiptHandleExpired, format!("{handle} is no longer usable")))
    }

    pub fn delete(&mut self, key: u64) {
        self.remove(key);
    }

    pub fn set_in_flight_until(&mut self, key: u64, until: u64) {
        if let Some(Message { hold: Hold::InFlight { until: end, .. }, .. }) = self.messages.get_mut(&key) {
            *end = until;
        }
    }
}
