//! The whole service state and command execution.

use std::collections::BTreeMap;
use std::ops::Bound;

use serde_json::{json, Map, Value};

use crate::command::{parse_line, AttributeInput, Command};
use crate::error::{Error, ErrorCode, Result};
use crate::queue::{
    Attributes, DeadLetter, Hold, Message, MessageId, Original, Queue, QueueName, ReceiptHandle,
};

const MAX_QUEUES: usize = 1000;

pub struct Broker {
    now: u64,
    queues: BTreeMap<QueueName, Queue>,
    next_message: u64,
    next_receipt: u64,
}

impl Default for Broker {
    fn default() -> Self {
        Self { now: 0, queues: BTreeMap::new(), next_message: 1, next_receipt: 1 }
    }
}

fn no_such_queue(name: &str) -> Error {
    Error::new(ErrorCode::QueueDoesNotExist, format!("queue {name:?} does not exist"))
}

fn members(value: Value) -> Map<String, Value> {
    match value {
        Value::Object(map) => map,
        _ => Map::new(),
    }
}

impl Broker {
    pub fn new() -> Self {
        Self::default()
    }

    /// Runs one input line and returns its response object.
    pub fn handle_line(&mut self, line: &[u8]) -> Value {
        let result = parse_line(line)
            .and_then(|object| Command::parse(&object).and_then(|command| self.execute(command)));
        match result {
            Ok(mut members) => {
                members.insert("ok".to_owned(), Value::Bool(true));
                Value::Object(members)
            }
            Err(error) => error.to_response(),
        }
    }

    fn queue_mut(&mut self, name: &str) -> Result<&mut Queue> {
        let now = self.now;
        let queue = self.queues.get_mut(name).ok_or_else(|| no_such_queue(name))?;
        queue.sweep(now);
        Ok(queue)
    }

    fn existing_dead_letter(&self, name: &str, fifo: bool) -> Result<DeadLetterTarget> {
        let (key, queue) = self.queues.get_key_value(name).ok_or_else(|| no_such_queue(name))?;
        if queue.attributes.fifo != fifo {
            return Err(Error::invalid("DeadLetterQueue", "must have the same Fifo setting as the queue"));
        }
        Ok(DeadLetterTarget(key.clone()))
    }

    pub fn execute(&mut self, command: Command<'_>) -> Result<Map<String, Value>> {
        match command {
            Command::CreateQueue { name, attributes } => self.create_queue(name, &attributes).map(|()| Map::new()),
            Command::SetQueueAttributes { queue, attributes } => {
                self.set_attributes(queue, &attributes).map(|()| Map::new())
            }
            Command::GetQueueAttributes { queue } => {
                let now = self.now;
                let queue = self.queue_mut(queue)?;
                let a = &queue.attributes;
                let mut attributes = json!({
                    "VisibilityTimeout": a.visibility_timeout,
                    "DelaySeconds": a.delay_seconds,
                    "RetentionSeconds": a.retention_seconds,
                    "Fifo": a.fifo,
                    "ContentBasedDeduplication": a.content_based_deduplication,
                });
                if let (Some(dead), Value::Object(map)) = (&a.dead_letter, &mut attributes) {
                    map.insert("DeadLetterQueue".to_owned(), json!(dead.queue.as_str()));
                    map.insert("MaxReceiveCount".to_owned(), json!(dead.max_receive_count));
                }
                let [visible, in_flight, delayed] = queue.counts(now);
                Ok(members(json!({
                    "Attributes": attributes,
                    "Counts": {"Visible": visible, "InFlight": in_flight, "Delayed": delayed},
                })))
            }
            Command::ListQueues { prefix } => {
                let prefix = prefix.unwrap_or_default();
                let names: Vec<&str> = self
                    .queues
                    .range::<str, _>((Bound::Included(prefix), Bound::Unbounded))
                    .map(|(name, _)| name.as_str())
                    .take_while(|name| name.starts_with(prefix))
                    .collect();
                Ok(members(json!({"QueueNames": names})))
            }
            Command::DeleteQueue { queue } => {
                self.queue_mut(queue)?;
                self.queues.remove(queue);
                for other in self.queues.values_mut() {
                    if other.attributes.dead_letter.as_ref().is_some_and(|d| d.queue.as_str() == queue) {
                        other.attributes.dead_letter = None;
                    }
                }
                Ok(Map::new())
            }
            Command::PurgeQueue { queue } => {
                self.queue_mut(queue)?.purge();
                Ok(Map::new())
            }
            Command::Tick { seconds } => {
                self.now += u64::from(seconds);
                Ok(members(json!({"Now": self.now})))
            }
            Command::SendMessage { queue, body, delay_seconds, group_id, deduplication_id } => {
                self.send(queue, body, delay_seconds, group_id, deduplication_id)
            }
            Command::ReceiveMessage { queue, max_messages, visibility_timeout } => {
                self.receive(queue, max_messages, visibility_timeout)
            }
            Command::DeleteMessage { queue, receipt_handle } => {
                let (queue, key) = self.locate(queue, receipt_handle)?;
                queue.delete(key);
                Ok(Map::new())
            }
            Command::ChangeMessageVisibility { queue, receipt_handle, visibility_timeout } => {
                let until = self.now + u64::from(visibility_timeout);
                let (queue, key) = self.locate(queue, receipt_handle)?;
                queue.set_in_flight_until(key, until);
                Ok(Map::new())
            }
        }
    }

    fn create_queue(&mut self, name: QueueName, input: &AttributeInput<'_>) -> Result<()> {
        let fifo = input.fifo.unwrap_or(false);
        if name.as_str().ends_with(".fifo") != fifo {
            return Err(Error::new(
                ErrorCode::QueueNameInvalid,
                "a name ends in .fifo exactly when Fifo is true",
            ));
        }
        let content_based = input.content_based_deduplication.unwrap_or(false);
        if content_based && !fifo {
            return Err(Error::invalid("ContentBasedDeduplication", "requires a FIFO queue"));
        }
        let requested_dead = input.dead_letter()?;
        if let Some(existing) = self.queues.get(name.as_str()) {
            let current = &existing.attributes;
            let defaults = Attributes::default();
            let same = current.visibility_timeout == input.visibility_timeout.unwrap_or(defaults.visibility_timeout)
                && current.delay_seconds == input.delay_seconds.unwrap_or(defaults.delay_seconds)
                && current.retention_seconds == input.retention_seconds.unwrap_or(defaults.retention_seconds)
                && current.fifo == fifo
                && current.content_based_deduplication == content_based
                && current.dead_letter.as_ref().map(|d| (d.queue.as_str(), d.max_receive_count)) == requested_dead;
            return if same {
                Ok(())
            } else {
                Err(Error::new(ErrorCode::QueueAlreadyExists, "queue exists with different attributes"))
            };
        }
        let dead_letter = match requested_dead {
            Some((queue, max_receive_count)) => {
                let DeadLetterTarget(queue) = self.existing_dead_letter(queue, fifo)?;
                Some(DeadLetter { queue, max_receive_count })
            }
            None => None,
        };
        if self.queues.len() >= MAX_QUEUES {
            return Err(Error::new(ErrorCode::LimitExceeded, "1000 queues exist"));
        }
        let defaults = Attributes::default();
        let attributes = Attributes {
            visibility_timeout: input.visibility_timeout.unwrap_or(defaults.visibility_timeout),
            delay_seconds: input.delay_seconds.unwrap_or(defaults.delay_seconds),
            retention_seconds: input.retention_seconds.unwrap_or(defaults.retention_seconds),
            fifo,
            content_based_deduplication: content_based,
            dead_letter,
        };
        self.queues.insert(name, Queue::new(attributes));
        Ok(())
    }

    fn set_attributes(&mut self, name: &str, input: &AttributeInput<'_>) -> Result<()> {
        let fifo = self.queue_mut(name)?.attributes.fifo;
        if input.fifo.is_some() {
            return Err(Error::new(ErrorCode::UnsupportedOperation, "the type of a queue cannot change"));
        }
        if input.content_based_deduplication == Some(true) && !fifo {
            return Err(Error::invalid("ContentBasedDeduplication", "requires a FIFO queue"));
        }
        let dead_letter = match input.dead_letter()? {
            Some((target, max_receive_count)) => {
                if !self.queues.contains_key(target) {
                    return Err(no_such_queue(target));
                }
                if target == name {
                    return Err(Error::invalid("DeadLetterQueue", "must not be the queue itself"));
                }
                let DeadLetterTarget(queue) = self.existing_dead_letter(target, fifo)?;
                Some(DeadLetter { queue, max_receive_count })
            }
            None => None,
        };
        let now = self.now;
        let queue = self.queue_mut(name)?;
        let a = &mut queue.attributes;
        a.visibility_timeout = input.visibility_timeout.unwrap_or(a.visibility_timeout);
        a.delay_seconds = input.delay_seconds.unwrap_or(a.delay_seconds);
        a.content_based_deduplication = input.content_based_deduplication.unwrap_or(a.content_based_deduplication);
        if dead_letter.is_some() {
            a.dead_letter = dead_letter;
        }
        if let Some(seconds) = input.retention_seconds {
            queue.set_retention(seconds, now);
        }
        Ok(())
    }

    fn send(
        &mut self,
        name: &str,
        body: &str,
        delay: Option<u32>,
        group: Option<&str>,
        dedup: Option<&str>,
    ) -> Result<Map<String, Value>> {
        let (now, id) = (self.now, MessageId(self.next_message));
        let queue = self.queue_mut(name)?;
        let a = &queue.attributes;
        if !a.fifo && (group.is_some() || dedup.is_some()) || a.fifo && delay.is_some() {
            return Err(Error::new(ErrorCode::UnsupportedOperation, "not supported by this type of queue"));
        }
        let mut dedup_id = None;
        if a.fifo {
            let group = group.ok_or_else(|| Error::missing("GroupId"))?;
            let id_text = match dedup {
                Some(text) => text,
                None if a.content_based_deduplication => body,
                None => return Err(Error::missing("DeduplicationId")),
            };
            if let Some(original) = queue.duplicate_of(id_text, now) {
                return Ok(members(json!({"MessageId": original.id.to_string(), "SequenceNumber": original.sequence})));
            }
            dedup_id = Some((group, id_text));
        }
        if queue.is_full() {
            return Err(Error::new(ErrorCode::LimitExceeded, "queue holds 100000 messages"));
        }
        let delay = delay.unwrap_or(queue.attributes.delay_seconds);
        let hold = match delay {
            0 => Hold::Released,
            d => Hold::Delayed { until: now + u64::from(d) },
        };
        let sequence = queue.add(id, body.to_owned(), now, dedup_id.map(|(g, _)| g.to_owned()), hold);
        let mut result = json!({"MessageId": id.to_string()});
        if let (Some(sequence), Some((_, text))) = (sequence, dedup_id) {
            queue.record_dedup(text, Original { accepted_at: now, id, sequence });
            result["SequenceNumber"] = json!(sequence);
        }
        self.next_message += 1;
        Ok(members(result))
    }

    fn receive(&mut self, name: &str, max: usize, visibility: Option<u32>) -> Result<Map<String, Value>> {
        let now = self.now;
        let mut next_receipt = self.next_receipt;
        let queue = self.queue_mut(name)?;
        let visibility = visibility.unwrap_or(queue.attributes.visibility_timeout);
        let delivery = queue.receive(now, max, visibility, &mut next_receipt);
        self.next_receipt = next_receipt;
        if let Some((target, moved)) = delivery.dead {
            let target = self
                .queues
                .get_mut(target.as_str())
                .expect("dead-letter queue exists: DeleteQueue clears every reference to it");
            for message in moved {
                target.add_dead(reset(message), now);
            }
        }
        let messages: Vec<Value> = delivery.delivered.iter().map(delivered_json).collect();
        Ok(members(json!({"Messages": messages})))
    }

    fn locate(&mut self, name: &str, handle: &str) -> Result<(&mut Queue, u64)> {
        let now = self.now;
        let next = self.next_receipt;
        let queue = self.queue_mut(name)?;
        let handle = ReceiptHandle::parse_issued(handle, next)
            .ok_or_else(|| Error::new(ErrorCode::ReceiptHandleInvalid, "receipt handle was never issued"))?;
        let key = queue.in_flight_key(handle, now)?;
        Ok((queue, key))
    }
}

struct DeadLetterTarget(QueueName);

fn reset(mut message: Message) -> Message {
    message.receive_count = 0;
    message.first_received_at = None;
    message.hold = Hold::Released;
    message
}

fn delivered_json(message: &Message) -> Value {
    let mut value = json!({
        "MessageId": message.id.to_string(),
        "ReceiptHandle": match message.hold {
            Hold::InFlight { handle, .. } => handle.to_string(),
            _ => String::new(),
        },
        "Body": message.body,
        "ReceiveCount": message.receive_count,
        "SentAt": message.sent_at,
        "FirstReceivedAt": message.first_received_at,
    });
    if let Some(fifo) = &message.fifo {
        value["GroupId"] = json!(fifo.group);
        value["SequenceNumber"] = json!(fifo.sequence);
    }
    value
}
