//! miniq: a small in-memory message queue driven by line-delimited JSON commands.

pub mod broker;
pub mod command;
pub mod error;
pub mod queue;

use std::io::{self, BufRead, Write};

/// Answers every line of `input` with one response line on `output`, flushing each.
pub fn run(mut input: impl BufRead, mut output: impl Write) -> io::Result<()> {
    let mut broker = broker::Broker::new();
    let mut line = Vec::new();
    loop {
        line.clear();
        if input.read_until(b'\n', &mut line)? == 0 {
            return Ok(());
        }
        if line.last() == Some(&b'\n') {
            line.pop();
        }
        serde_json::to_writer(&mut output, &broker.handle_line(&line))?;
        output.write_all(b"\n")?;
        output.flush()?;
    }
}
