use serde_json::{json, Value};

fn session(lines: &[&str]) -> Vec<Value> {
    let input = lines.join("\n");
    let mut output = Vec::new();
    miniq::run(input.as_bytes(), &mut output).expect("in-memory io cannot fail");
    String::from_utf8(output)
        .expect("responses are UTF-8")
        .lines()
        .map(|l| serde_json::from_str(l).expect("each response is JSON"))
        .collect()
}

#[test]
fn send_receive_delete_round_trip() {
    let out = session(&[
        r#"{"Command":"CreateQueue","QueueName":"jobs"}"#,
        r#"{"Command":"SendMessage","QueueName":"jobs","Body":"hi"}"#,
        r#"{"Command":"ReceiveMessage","QueueName":"jobs"}"#,
        r#"{"Command":"DeleteMessage","QueueName":"jobs","ReceiptHandle":"r-1"}"#,
        r#"{"Command":"DeleteMessage","QueueName":"jobs","ReceiptHandle":"r-1"}"#,
    ]);
    assert_eq!(out[0], json!({"ok": true}));
    assert_eq!(out[1], json!({"ok": true, "MessageId": "m-1"}));
    assert_eq!(
        out[2],
        json!({"ok": true, "Messages": [{"MessageId": "m-1", "ReceiptHandle": "r-1", "Body": "hi",
            "ReceiveCount": 1, "SentAt": 0, "FirstReceivedAt": 0}]})
    );
    assert_eq!(out[3], json!({"ok": true}));
    assert_eq!(out[4]["error"]["code"], "ReceiptHandleExpired");
}

#[test]
fn bad_lines_get_error_codes() {
    let out = session(&["", r#"{"Command":"Nope"}"#, r#"{"Command":"Tick"}"#, r#"{"Command":"Tick","Seconds":1.0}"#]);
    let codes: Vec<&Value> = out.iter().map(|r| &r["error"]["code"]).collect();
    assert_eq!(codes, ["InvalidRequest", "InvalidRequest", "MissingParameter", "InvalidParameterValue"]);
}
